package dev.yaclient.modules;

import dev.yaclient.Setting;
import org.lwjgl.input.Keyboard;
import org.lwjgl.input.Mouse;
import org.lwjgl.opengl.Display;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.SourceDataLine;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Mechvibes: a mechanical keyboard sound for every key you press (and release). The sounds are generated by the
 * client itself (no files), mixed on one audio line, and played from a small background thread that watches the keys,
 * so it works in game, in the chat and in menus and never touches the render thread.
 */
public class MechvibesModule extends Module {
    private static final String[] PROFILES = {"mv_blue", "mv_brown", "mv_red", "mv_typewriter", "mv_bubble", "mv_creamy"};

    private final Setting.Choice sound = add("general", new Setting.Choice("sound", 1, PROFILES));
    private final Setting.Num volume = add("general", new Setting.Num("volume", 0f, 100f, 5f, 60f, "%"));
    private final Setting.Bool release = add("general", new Setting.Bool("key_release", true));
    private final Setting.Bool mouse = add("general", new Setting.Bool("mouse_clicks", false));
    private final Setting.Bool inMenus = add("general", new Setting.Bool("in_menus", true));

    public MechvibesModule() { super("mechvibes", Category.UTILITY, false); }

    private static final int RATE = 44100;
    private Thread thread;

    @Override
    public void onAlwaysTick() {
        if (thread == null && enabled) {
            thread = new Thread(this::loop, "YA-Mechvibes");
            thread.setDaemon(true);
            thread.start();
        }
    }

    private static final class Voice {
        final short[] d; int pos; final float gain;
        Voice(short[] d, float gain) { this.d = d; this.gain = gain; }
    }

    // ---- audio thread ----
    private void loop() {
        SourceDataLine line;
        try {
            line = AudioSystem.getSourceDataLine(new AudioFormat(RATE, 16, 1, true, false));
            line.open(new AudioFormat(RATE, 16, 1, true, false), 4096);
            line.start();
        } catch (Throwable t) { return; }   // no audio device: the mod simply stays silent
        final List<Voice> voices = new ArrayList<Voice>();
        final boolean[] prev = new boolean[256];
        boolean prevL = false, prevR = false;
        int builtFor = -1;
        short[][][] bank = null;   // [kind][variant] kind: 0 down, 1 down big, 2 up, 3 up big
        Random rnd = new Random();
        final int CH = 128;
        final byte[] out = new byte[CH * 2];
        final float[] mix = new float[CH];
        while (true) {
            try {
                boolean active = enabled && mc != null && Display.isActive() && Keyboard.isCreated();
                if (active && (inMenus.value || mc.currentScreen == null)) {
                    if (builtFor != sound.index || bank == null) { bank = build(sound.index); builtFor = sound.index; }
                    float g = Math.max(0f, Math.min(1f, volume.value / 100f)) * 0.8f;
                    for (int k = 1; k < 256; k++) {
                        boolean d = Keyboard.isKeyDown(k);
                        if (d != prev[k]) {
                            prev[k] = d;
                            if (d || release.value) {
                                boolean big = k == Keyboard.KEY_SPACE || k == Keyboard.KEY_RETURN || k == Keyboard.KEY_LSHIFT || k == Keyboard.KEY_RSHIFT
                                        || k == Keyboard.KEY_BACK || k == Keyboard.KEY_TAB || k == Keyboard.KEY_CAPITAL;
                                short[] s = bank[(d ? 0 : 2) + (big ? 1 : 0)][rnd.nextInt(3)];
                                if (voices.size() < 24) voices.add(new Voice(s, d ? g : g * 0.7f));
                            }
                        }
                    }
                    if (mouse.value && Mouse.isCreated()) {
                        boolean l = Mouse.isButtonDown(0), r = Mouse.isButtonDown(1);
                        if (l && !prevL || r && !prevR) voices.add(new Voice(bank[0][rnd.nextInt(3)], g));
                        prevL = l; prevR = r;
                    }
                } else {
                    java.util.Arrays.fill(prev, false);
                    if (!enabled) { voices.clear(); }
                }
                java.util.Arrays.fill(mix, 0f);
                for (int i = voices.size() - 1; i >= 0; i--) {
                    Voice v = voices.get(i);
                    for (int n = 0; n < CH && v.pos < v.d.length; n++, v.pos++) mix[n] += v.d[v.pos] * v.gain;
                    if (v.pos >= v.d.length) voices.remove(i);
                }
                for (int n = 0; n < CH; n++) {
                    int s = Math.max(-32768, Math.min(32767, Math.round(mix[n])));
                    out[2 * n] = (byte) s; out[2 * n + 1] = (byte) (s >> 8);
                }
                line.write(out, 0, out.length);   // blocks until the line has room: this is the pacing
            } catch (Throwable t) {
                try { Thread.sleep(50); } catch (InterruptedException e) { return; }
            }
        }
    }

    // ---- sound synthesis ----
    private static short[][][] build(int profile) {
        short[][][] b = new short[4][3][];
        for (int v = 0; v < 3; v++) {
            b[0][v] = gen(profile, false, false, v);
            b[1][v] = gen(profile, true, false, v);
            b[2][v] = gen(profile, false, true, v);
            b[3][v] = gen(profile, true, true, v);
        }
        return b;
    }

    private static void sine(float[] b, float t0, float f, float tau, float amp) {
        int s0 = (int) (t0 * RATE);
        for (int i = s0; i < b.length; i++) {
            float t = (i - s0) / (float) RATE;
            if (t > tau * 7f) break;
            b[i] += amp * (float) (Math.sin(2 * Math.PI * f * t) * Math.exp(-t / tau));
        }
    }

    private static void noise(float[] b, Random r, float t0, float tau, float amp, float lp) {
        int s0 = (int) (t0 * RATE);
        float comp = 0.5f * (float) Math.sqrt((2f - lp) / lp), y = 0f;
        for (int i = s0; i < b.length; i++) {
            float t = (i - s0) / (float) RATE;
            if (t > tau * 7f) break;
            y += lp * ((r.nextFloat() * 2f - 1f) - y);
            b[i] += amp * comp * y * (float) Math.exp(-t / tau);
        }
    }

    private static short[] gen(int p, boolean big, boolean up, int variant) {
        Random r = new Random(p * 1000L + variant * 10L + (big ? 1 : 0) + (up ? 100 : 0));
        float pitch = (1f + (variant - 1) * 0.07f) * (big ? 0.72f : 1f);
        float len = up ? 0.07f : (p == 5 ? 0.22f : 0.18f);
        float[] b = new float[(int) (len * RATE)];
        if (up) {
            float f = p == 0 || p == 3 ? 2400f : p == 4 ? 1300f : 1500f;
            sine(b, 0f, f * pitch, 0.005f, 0.35f);
            noise(b, r, 0f, 0.003f, 0.35f, 0.5f);
        } else switch (p) {
            case 0:   // blue: sharp click + click jacket + bottom out
                sine(b, 0f, 900f * pitch, 0.020f, 0.5f);
                noise(b, r, 0f, 0.004f, 0.9f, 0.55f);
                noise(b, r, 0.011f, 0.003f, 0.6f, 0.6f);
                sine(b, 0.011f, 3200f * pitch, 0.006f, 0.25f);
                sine(b, 0.045f, 700f * pitch, 0.020f, 0.35f);
                noise(b, r, 0.045f, 0.010f, 0.4f, 0.3f);
                break;
            case 1:   // brown: soft tactile
                sine(b, 0f, 620f * pitch, 0.030f, 0.6f);
                noise(b, r, 0f, 0.006f, 0.6f, 0.25f);
                sine(b, 0.035f, 480f * pitch, 0.030f, 0.4f);
                noise(b, r, 0.035f, 0.008f, 0.3f, 0.2f);
                break;
            case 2:   // red: linear thock
                sine(b, 0f, 380f * pitch, 0.045f, 0.7f);
                noise(b, r, 0f, 0.008f, 0.45f, 0.15f);
                sine(b, 0.03f, 300f * pitch, 0.050f, 0.4f);
                break;
            case 3:   // typewriter: metallic strike
                sine(b, 0f, 1400f * pitch, 0.050f, 0.35f);
                sine(b, 0f, 2300f * pitch, 0.040f, 0.25f);
                sine(b, 0f, 3100f * pitch, 0.030f, 0.18f);
                noise(b, r, 0f, 0.003f, 1.0f, 0.7f);
                noise(b, r, 0.025f, 0.006f, 0.6f, 0.4f);
                sine(b, 0.025f, 200f * pitch, 0.050f, 0.5f);
                break;
            case 4: { // bubble pop: a quick falling-then-rising blip
                double ph = 0;
                for (int i = 0; i < b.length; i++) {
                    float t = i / (float) RATE;
                    double f = (380 + 900 * (1 - Math.exp(-t / 0.02))) * pitch;
                    ph += 2 * Math.PI * f / RATE;
                    b[i] += 0.8f * (float) (Math.sin(ph) * Math.exp(-t / 0.03));
                }
                break;
            }
            default:  // creamy: deep, round thock
                sine(b, 0f, 240f * pitch, 0.060f, 0.8f);
                sine(b, 0f, 160f * pitch, 0.080f, 0.5f);
                noise(b, r, 0f, 0.008f, 0.35f, 0.10f);
        }
        float peak = 0.0001f;
        for (float v : b) peak = Math.max(peak, Math.abs(v));
        short[] out = new short[b.length];
        int fade = (int) (0.0006f * RATE);
        for (int i = 0; i < b.length; i++) {
            float v = b[i] / peak * 0.9f * (i < fade ? i / (float) fade : 1f);
            out[i] = (short) Math.round(v * 32000f);
        }
        return out;
    }
}
